INSERT INTO campaigns (title,description,host_organizer,campaign_url,image_url,start_date,end_date,region,category,status,submission_type) VALUES ('창원시민안전체험관 환경정화 방역봉사(창원과학체험관 3층)','만19세 이상 선착순 모집, 2025년 11월 1~30일 14~18시(일 4시간) 창원과학체험관(3층)에서 환경정화 및 소독·방역 봉사. 4시간 근무 시 교통비·식비 실비 지급·봉사실적 1365포털 등재, 불참 2회시 제한','창원시민안전체험관 운영지원팀','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3358067**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3358067)','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3358067**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3358067)','2025-11-01','2025-11-30','경남 창원시 성산구 충혼로72번길 16, 창원과학체험관 3층 시민안전체험관','TRANSPORTATION','ACTIVE','MANUAL_GUIDE'),('치악산국립공원 탐방로 환경정화 봉사','원주시 치악산국립공원사무소~비로봉 구간 내 모든 구간에서 진행, 저지대(4시간)·고지대(8시간) 인정. 탐방로·주차장·계곡길·봉 정상 등에서 환경정화, 신청 후 현장(사무소) 방문, 시작·종료기록대장, 사진인증 필수','치악산국립공원사무소(강원 원주시 소초면 무쇠점2길 26, 1365포털·현장 신청)','https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3354908','https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3354908','2025-10-01','2025-12-31','강원도 원주시 소초면 치악산국립공원사무소~비로봉 구간, 등산로·계곡·주차장·정상 포함','CONSERVATION','ACTIVE','MANUAL_GUIDE'),('태백산국립공원 환경정화자원봉사','태백산 당골계곡·유일사 탐방로 등 일원에서 진행, 1365포털 신청 후 소도분소 봉사기록대장 작성, 1일 최대 4시간 인증. 현장사진·직원확인 필수, 기상특보 시 봉사 불가. 등산화 등 개인안전용품 반드시 준비','태백산국립공원사무소 소도분소(태백시 천제단길 181), 국립공원자원봉사센터','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3346280**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3346280)','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3346280**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3346280)','2025-09-05','2025-12-05','강원도 태백시 태백산국립공원 일원(당골계곡, 유일사 탐방로, 등)','CONSERVATION','ACTIVE','MANUAL_GUIDE'),('익산 남부시장 환경정화(2025년 하반기)','익산시 남부시장 일원(상가·사무실)에서 2025.9.2~12.2까지 평일·토요일 매일 13~18시 내 최대 5시간 환경정화 집단봉사. 모집정원 20명/일, 청소년·기업·단체·성인 누구나 참여. 사전에 신청 후 2층 사무실로 방문','남부시장 상인회(익산시, 담당 양은수 063-855-4798)','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3343055**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3343055)','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3343055**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3343055)','2025-09-02','2025-12-02','전북특별자치도 익산시 평동로11길 12 남부시장 2층상인회 사무실','CONSERVATION','EXPECT','MANUAL_GUIDE'),('무등산국립공원동부사무소 환경정화/ASF·산림병해충 예찰 자원봉사','전남 화순 만연탐방지원센터에서 10~17시 내 일 최대 7시간, 환경정화·ASF(돼지열병)·산림병해충 예찰, 현장 직원 확인 및 기록. 청소년은 전화확인/보호자 동반, 안전장비 필수. 단체, NGO 등 사전연락 권장','무등산국립공원동부사무소 만연탐방지원센터(061-371-1187), 국립공원자원봉사센터, 1365포털','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3360845**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3360845)','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3360845**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3360845)','2025-10-01','2025-12-31','전남 화순군 화순읍 진각로357-6 만연탐방지원센터, 무등산국립공원동부 일원','CONSERVATION','ACTIVE','MANUAL_GUIDE'),('강서구 자원봉사센터 탄소중립 코스 줍깅(2025)','강서구 명소·공원·가맹점 등 지정코스에서 환경정화 위한 줍깅(줍다+조깅), 청소년·성인 자원봉사자 누구나 참여. 1코스 1시간, 일 2시간·월 8시간 제한, 시간·장소·얼굴·봉투 인증사진+결과보고서 필수. 결과보고서 허위·사진편집 시 실적 미인정','강서구자원봉사센터 (메일:  [**26005331@gangseo.seoul.kr**](mailto:26005331@gangseo.seoul.kr))','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3355256**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3355256)','[**https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3355256**](https://www.1365.go.kr/vols/P9230/partcptn/grpCptn.do?type=show&progrmRegistNo=3355256)','2025-10-20','2025-11-28','서울 강서구 주요 명소·공원·가맹점 등 지정코스','ENERGY','EXPE